(1, N'Ấm Trà Lẻ Men Lam Vẽ Vàng Họa Tiết Hoa Sen', 300000, N'am-tra-le-men-lam-ve-vang-hoa-tiet-hoa-sen_7bf0e5afc62347b1bf63ada308698dc5_medium.jpg', N'am-tra-le-men-lam-ve-vang-hoa-tiet-hoa-sen', N'Ấm Trà Lẻ Men Lam Vẽ Vàng Họa Tiết Hoa Sen, Đồ Thờ Bát Tràng Men Lam Vẽ Vàng, Đồ Thờ Bát Tràng, Ấm chén thờ, video_6WuMdvnHja4, phanloai_ấm chén thờ, vẽ vàng, men lam, đồ thờ Bát Tràng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ấm Trà Lẻ Men Lam Vẽ Vàng Họa Tiết Hoa Sen', N'<ul><li><strong>Tên sản phẩm</strong>: Ấm Trà Lẻ Men Lam Vẽ Vàng Họa Tiết Hoa Sen</li><li><strong>Kích thước</strong>: Chiều cao H7</li><li><strong>Chất liệu</strong>: Gốm sứ men lam vẽ vàng 24K </li><li><strong>Họa tiết</strong>: Hoa Sen</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Đựng trà, giúp xua đuổi ma quỷ mang đến cho con người cuộc sống bình an, hạnh phúc</li><li><strong>Ý nghĩa:</strong> Dòng nước chảy từ ấm trà có ý nghĩa truyền phúc đức từ đời trước cho đời sau.</li></ul>'),
(1, N'Ấm Trà Lẻ Men Rạn Nổi Hoạ Tiết Hoa Đào', 180000, N'am-tra-le-men-ran-noi-hoa-tiet-hoa-dao_84d841b4fc384406850895afe6eaaab1_medium.jpg', N'am-tra-le-men-ran-noi-hoa-tiet-hoa-dao', N'Ấm Trà Lẻ Men Rạn Nổi Hoạ Tiết Hoa Đào, Đồ Thờ Bát Tràng Men Rạn, Đồ Thờ Bát Tràng, phanloai_ấm chén thờ, men rạn, đồ thờ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ấm Trà Lẻ Men Rạn Nổi Hoạ Tiết Hoa Đào với chất men rạn nổi đặc trưng của gốm sứ Bát Tràng. Họa tiết hoa đào được khắc vẽ trên sản phẩm là một tác phẩm nghệ thuật tinh tế, được chế tác từ chất gốm sứ cao cấp.', N'<ul><li><strong>Tên sản phẩm</strong>: Ấm Trà Lẻ Men Rạn Nổi Hoạ Tiết Hoa Đào</li><li><strong>Kích thước</strong>: Chiều cao H8</li><li><strong>Chất liệu</strong>: Gốm sứ men rạn nổi </li><li><strong>Họa tiết</strong>: Hoa Đào</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Đựng trà, giúp xua đuổi ma quỷ mang đến cho con người cuộc sống bình an, hạnh phúc</li><li><strong>Ý nghĩa:</strong> Hóa giải hung khí và mang đến cát khí, tài lộc, thịnh vượng cho gia chủ.</li></ul>'),
(1, N'Ấm Trà Lẻ Thờ Cúng Men Rạn Vẽ Vàng Họa Tiết Hoa Đào', 1450000, N'am-tra-le-ran-vang__2__9435f07ce47b438ea70aaace16b51f89_medium.jpg', N'am-tra-le-tho-cung-men-ran-ve-vang-hoa-tiet-hoa-dao', N'Ấm Trà Lẻ Thờ Cúng Men Rạn Vẽ Vàng Họa Tiết Hoa Đào, Đồ Thờ Bát Tràng Men Rạn Vẽ Vàng, Đồ Thờ Bát Tràng, phanloai_ấm chén thờ, vẽ vàng, men rạn, đồ thờ bát tràng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ấm Trà Lẻ Thờ Cúng Men Rạn Vẽ Vàng Họa Tiết Hoa Đào là sản phẩm được đầu tư trong khâu sản xuất và phân phối bởi Không Gian Gốm Bát Tràng. Ấm trà nhỏ gọn, phù hợp cho không gian thờ cúng. Ấm có thể đựng được lượng trà tương đối cho bộ 3 chén hoặc 5 chén trà. Đây là biểu tượng của sự tôn trọng và tri ân với tổ tiên.', N'<ul><li><strong>Tên sản phẩm</strong>: Ấm Trà Lẻ Thờ Cúng Men Rạn Vẽ Vàng Họa Tiết Hoa Đào</li><li><strong>Kích thước</strong>: Ấm cao 8cm, ngang 15cm luôn quai </li><li><strong>Chất liệu</strong>: Gốm sứ men rạn họa tiết đắp nổi vẽ vàng 24K </li><li><strong>Họa tiết</strong>: Hoa đào</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Đựng trà cúng bàn thờ</li><li><strong>Ý nghĩa:</strong> Hoa đào là tinh hoa của Ngũ hành giúP xua đuổi ma quỷ mang đến cho con người cuộc sống bình an, hạnh phúc</li><li><strong>Lưu ý</strong>: Gia chủ nên mua đĩa kê và chén trà theo bộ 3 hoặc 5 chén đồng bộ về màu men và họa tiết.</li></ul>'),
(1, N'Bát Cơm Thờ Kim Long Đẳng Vân Men Lam Nổi Vẽ Vàng Kim', 1240000, N'bat-com-tho-kim-long-dang-van-men-lam-noi-ve-vang-kim_450eeb358329407cb063e660762aa607_medium.jpg', N'bat-com-tho-kim-long-dang-van-men-lam-noi-ve-vang-kim', N'Bát Cơm Thờ Kim Long Đẳng Vân Men Lam Nổi Vẽ Vàng Kim, Đồ Thờ Bát Tràng Men Lam Nổi Vẽ Vàng, Đồ Thờ Bát Tràng, video_O27pIMJgQ1Y, phanloai_bát cơm thờ, vẽ vàng, men lam, đồ thờ Bát Tràng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bát Cơm Thờ Kim Long Đẳng Vân Men Lam Nổi Vẽ Vàng Kim thường có trên bàn thờ gia tiên hoặc bàn thờ Phật. Bát cơm dày dặn, cứng cáp và cầm chắc tay với họa tiết rồng xanh được vẽ vàng uy mãnh, đường nét mềm mại.', N'<ul><li><strong>Tên sản phẩm</strong>: Bát Cơm Thờ Kim Long Đẳng Vân Men Lam Nổi Vẽ Vàng Kim</li><li><strong>Kích thước</strong>: Chiều cao H6, đường kính miệng bát: phi 11</li><li><strong>Họa tiết</strong>: Rồng Vàng</li><li><strong>Chất liệu</strong>: Gốm sứ men lam nổi vẽ vàng kim 24K</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Đựng cơm cúng và trưng bày trên bàn thờ, giúp cho không gian thờ cúng thanh tịnh</li><li><strong>Ý nghĩa:</strong> Hóa giải hung khí và mang đến cát khí, tài lộc, thịnh vượng cho gia chủ.</li></ul>'),
(1, N'Bát Cơm Thờ Men Lam Họa Tiết Hoa Sen', 80000, N'bat-com-men-lam-hoa-tiet-hoa-sen_9433c6c8c64a4aec9485c8c16ee58307_medium.jpg', N'bat-com-tho-men-lam-hoa-tiet-hoa-sen', N'Bát Cơm Thờ Men Lam Họa Tiết Hoa Sen, Đồ Thờ Bát Tràng Men Lam, Đồ Thờ Bát Tràng, Bát cơm thờ, phanloai_bát cơm thờ, men lam, đồ thờ Bát Tràng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bát Cơm Thờ Men Lam Họa Tiết Hoa Sen được coi là biểu tượng của sự linh thiêng của trời đất, là nơi chứa đựng năng lượng thuần khiết và trong lành, thể hiện lòng thành kính của con cháu đối với tổ tiên và các vị thần, đồng thời kèm theo mong muốn cho sự thịnh vượng và những điều tốt lành.', N'<ul><li><strong>Tên sản phẩm</strong>: Bát Cơm Thờ Men Lam Họa Tiết Hoa Sen</li><li><strong>Họa tiết</strong>: Hoa Sen</li><li><strong>Chất liệu</strong>: Gốm sứ men lam</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Đựng cơm cúng và trưng bày trên bàn thờ, giúp cho không gian thờ cúng thanh tịnh</li><li><strong>Ý nghĩa:</strong> Hóa giải hung khí và mang đến cát khí, tài lộc, thịnh vượng cho gia chủ.</li></ul>'),
