(1, N'Bát Hương Men Hoàng Tộc Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt', 4620000, N'bat-huong-men-hoang-toc-ve-vang-hoa-tiet-song-long-chau-nguyet_78e2e4edf7a64345be46907a53635dc5_medium.jpg', N'bat-huong-men-hoang-toc-ve-vang-hoa-tiet-song-long-chau-nguyet', N'Bát Hương Men Hoàng Tộc Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt, Đồ Thờ Bát Tràng Men Hoàng Tộc, Đồ Thờ Bát Tràng, Bát hương, phanloai_bát hương, men hoàng thổ, đồ thờ Bát Tràng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bát Hương Men Hoàng Tộc Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt là vật phẩm quan trọng nhất trên bàn thờ. Bát hương đặt ở trung tâm bàn thờ dùng để cắm hương và thực hiện các nghi thức thờ cúng.', N'<ul><li><strong>Tên sản phẩm</strong>: Bát Hương Men Hoàng Tộc Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt</li><li><strong>Kích thước</strong>: Đường kính Ø12, Ø14, Ø16, Ø18, Ø20</li><li><strong>Họa tiết</strong>: Song Long Chầu Nguyệt</li><li><strong>Chất liệu</strong>: Gốm sứ men hoàng tộc vẽ vàng</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Dùng để cắm hương sau khi thắp, thực hiện các nghi thức thờ cúng.</li><li><strong>Ý nghĩa:</strong> Kết nối giữa thế giới tâm linh, thông qua việc thắp hương trên bàn thờ.</li></ul>'),
(1, N'Bát Hương Men Lục Họa Tiết Song Long Chầu Nguyệt', 560000, N'bat-huong-men-luc-hoa-tiet-song-long-chau-nguyet_b1c747aaf31a493d89c239e0f0fee37c_medium.png', N'bat-huong-men-luc-hoa-tiet-song-long-chau-nguyet', N'Bát Hương Men Lục Họa Tiết Song Long Chầu Nguyệt, Đồ Thờ Bát Tràng Men Lục, Đồ Thờ Bát Tràng, phanloai_bát hương, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bát hương song long chầu nguyệt được tạo ra với sự tỉ mỉ trong quá trình tạo hình, tạo nên sự cân đối và hài hòa. Nghệ nhân Bát Tràng đã tận dụng khéo léo dòng men lục trang nhã, tượng trưng cho sự phát triển, sinh trưởng và tài lộc, để vẽ hoặc đắp nổi họa tiết song long chầu nguyệt tinh xảo.', N'<ul><li><strong>Tên sản phẩm</strong>: Bát Hương Men Lục Họa Tiết Song Long Chầu Nguyệt</li><li><strong>Kích thước</strong>: Phi Ø12, Ø14, Ø16, Ø18, Ø20, Ø22</li><li><strong>Chất liệu</strong>: Gốm sứ cao cấp </li><li><strong>Họa tiết</strong>: Song Long Chầu Nguyệt</li><li><strong>Công dụng</strong>: Dùng để cắm hương sau khi thắp, thực hiện các nghi thức thờ cúng.</li><li><strong>Ý nghĩa:</strong> Tăng sự trang nghiêm, thanh tịnh cho không gian thờ cúng và mang lại phong thủy tốt, giúp thu hút tài lộc, may mắn và năng lượng tích cực cho gia đình. </li><li><strong>Lưu ý:</strong> Gia chủ có thể sắm thêm đế kê bát hương cùng họa tiết cùng kích thước phi để kê dưới bát hương.</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li></ul>'),
(1, N'Bát Hương Men Rạn Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt', 5250000, N'bat-huong-ran-noi-song-long__4__bb9b6df61b6d49d3846c6c40f1cecd2f_medium.jpg', N'bat-huong-men-ran-ve-vang-hoa-tiet-song-long-chau-nguyet', N'Bát Hương Men Rạn Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt, Đồ Thờ Bát Tràng Men Rạn Vẽ Vàng, Đồ Thờ Bát Tràng, phanloai_bát hương, bát hương, vẽ vàng, men rạn, đồ thờ Bát Tràng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bát Hương Men Rạn Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt được làm từ gốm sứ đã được nung chín nên rất cứng cáp và chắc chắn. Bát hương vẽ vàng được nặn tỉ mỉ, tạo được sự cân đối trong tổng thể. Khi đặt sản phẩm lên bàn thờ gia tiên, chúng sẽ mang đến sự thanh lọc, điều hòa vượng khí cho không gian thờ cúng.', N'<ul><li><span style="font-size:14px"><strong>Tên sản phẩm</strong>: Bát Hương Men Rạn Vẽ Vàng Họa Tiết Song Long Chầu Nguyệt</span></li><li><span style="font-size:14px"><strong>Kích thước</strong>: Đường kính bát hương Ø12, Ø14, Ø16, Ø18, Ø20, Ø22, Ø24</span></li><li><span style="font-size:14px"><strong>Chất liệu</strong>: Gốm sứ men rạn họa tiết đắp nổi vẽ vàng 24K </span></li><li><span style="font-size:14px"><strong>Họa tiết</strong>: Song Long Chầu Ngọc</span></li><li><span style="font-size:14px"><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</span></li><li><span style="font-size:14px"><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </span></li><li><span style="font-size:14px"><strong>Công dụng</strong>: Dùng để cắm hương sau khi thắp, thực hiện các nghi thức thờ cúng.</span></li><li><span style="font-size:14px"><strong>Ý nghĩa:</strong> Họa tiết song long chầu nguyệt đem lại vận khí dồi dào, thu hút may mắn và thịnh vượng</span></li><li><span style="font-size:14px">Lưu ý: Gia chủ có thể sắm thêm đế kê bát hương cùng họa tiết cùng kích thước phi để kê dưới bát hương.</span></li></ul>'),
(1, N'Bát Hương Men Vàng Họa Tiết Song Long Chầu Nguyệt', 560000, N'bat-huong-men-vang-hoa-tiet-song-long-chau-nguyet-1_2150a50be93d45b2af13dc941e38a0e8_medium.png', N'bat-huong-men-vang-hoa-tiet-song-long-chau-nguyet', N'Bát Hương Men Vàng Họa Tiết Song Long Chầu Nguyệt, Đồ Thờ Bát Tràng Men Vàng, Đồ Thờ Bát Tràng, phanloai_bát hương, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Họa tiết được sử dụng làm chủ đạo trên sản phẩm là song long chầu nguyệt. Họa tiết này mang ý nghĩa sâu sắc trong văn hóa tâm linh người Việt. Rồng là loài linh vật hàng đầu trong Tứ linh, có sức mạnh và uy quyền cao nhất, là đại diện cho sự hòa hợp với âm dương nhật nguyệt.', N'<ul><li><strong>Tên sản phẩm</strong>: Bát Hương Men Vàng Họa Tiết Song Long Chầu Nguyệt</li><li><strong>Kích thước</strong>: Phi Ø12, Ø14, Ø16, Ø18, Ø20, Ø22</li><li><strong>Chất liệu</strong>: Gốm sứ cao cấp </li><li><strong>Họa tiết</strong>: Song Long Chầu Nguyệt</li><li><strong>Công dụng</strong>: Dùng để cắm hương sau khi thắp, thực hiện các nghi thức thờ cúng.</li><li><strong>Ý nghĩa:</strong> Tăng sự trang nghiêm, thanh tịnh cho không gian thờ cúng và mang lại phong thủy tốt, giúp thu hút tài lộc, may mắn và năng lượng tích cực cho gia đình. </li><li><strong>Lưu ý:</strong> Gia chủ có thể sắm thêm đế kê bát hương cùng họa tiết cùng kích thước phi để kê dưới bát hương.</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li></ul>'),
