(3, N'Đĩa Dài Sâu Lòng Ba Màu', 305000.0, N'dai-dien-3-mau-28_39384b24eaa343d091996a9dfd632aeb_medium.jpg', N'dia-dai-sau-long-ba-mau', N'Đĩa Dài Sâu Lòng Ba Màu, Bát Đĩa Gốm Sứ, phanloai_đĩa kiểu, bát đĩa, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Đĩa Dài Sâu Lòng Ba Màu là sự kết hợp giữa men nâu đất, men xanh ngọc và men trắng ngà. Sự pha trộn này tạo hiệu ứng chuyển màu mềm mại, tự nhiên, gợi lên cảm giác ấm áp và gần gũi nhưng vẫn rất sang trọng.', N'<ul><li><strong>Tên sản phẩm</strong>: Đĩa Dài Sâu Lòng Ba Màu</li><li><strong>Chất liệu</strong>: Sứ cao cấp</li><li><strong>Số lượng: </strong>Theo yêu cầu</li><li><strong>Họa tiết:</strong> Ba màu</li><li><strong>Màu men:</strong> Men nâu, men trắng, men xám</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Dùng để trình bày món ăn trên bàn tiệc và sử dụng cho bữa cơm gia đình, làm quà tặng.</li><li><strong>Ưu điểm:</strong> Sử dụng được trong lò vi sóng, dễ dàng cọ rửa, không xỉn màu, không mảng bám.</li></ul>'),
(3, N'Tô Cắt Ba Màu', NULL, N'dai_dien_3_mau-06_99d1a9c8b4d048a49ea672fe4558e9ea_medium.jpg', N'to-cat-ba-mau', N'Tô Cắt Ba Màu, Bát Đĩa Gốm Sứ, bát đĩa, phanloai_tô canh, phanloai_tô gốm sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Tô Cắt Ba Màu hình nón cụt sâu lòng, có đến ba kích thước cho khách hàng chọn lựa, sử dụng hay làm quà tặng vào những dịp như sinh nhật, tân gia, quà kỷ niệm, ...', N'<ul><li><strong>Tên sản phẩm</strong>: Tô Cắt Ba Màu</li><li><strong>Chất liệu</strong>: Gốm Sứ cao cấp</li><li><strong>Số lượng: </strong>Theo yêu cầu</li><li><strong>Họa tiết:</strong> Ba màu</li><li><strong>Màu men:</strong> Men nâu, men trắng, men xám</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Dùng để trình bày món ăn trên bàn thờ và sử dụng cho bữa cơm gia đình, làm quà tặng.</li><li><strong>Ưu điểm:</strong> Sử dụng được trong lò vi sóng, dễ dàng cọ rửa, không xỉn màu, không mảng bám.</li></ul>'),
(3, N'Đĩa Lá Xoài Men Trắng Vẽ Cá Đàn', 160000.0, N'dsc04125_8004f493138e41b29b5b4b5f6475d482_medium.jpg', N'dia-la-xoai-men-trang-ve-ca-dan', N'Đĩa Lá Xoài Men Trắng Vẽ Cá Đàn, Bát Đĩa Gốm Sứ, bát đĩa, phanloai_đĩa kiểu, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Không đơn thuần là vật dụng trong gia đình, Đĩa Lá Xoài Men Trắng Vẽ Cá Đàn còn chứa đựng nhiều ý nghĩa phong thủy và văn hóa. Trong quan niệm phương Đông, hình ảnh đàn cá gợi đến sự sung túc, thịnh vượng và sự thuận lợi trong công việc, cuộc sống.', N'<ul><li><strong>Tên sản phẩm: </strong>Đĩa Lá Xoài Men Trắng Vẽ Cá Đàn</li><li><strong>Chất liệu:</strong> Gốm sứ cao cấp</li><li><strong>Màu men: </strong>Men Trắng</li><li><strong>Họa tiết:</strong> Cá đàn</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li><strong>Công dụng:</strong> Dùng đựng cơm, trình bày món ăn trên bàn thờ và sử dụng cho bữa cơm gia đình, quà tặng, trang trí nội thất.</li><li><strong>Ưu điểm:</strong> Sử dụng được trong lò vi sóng, dễ dàng cọ rửa, không xỉn màu, không mảng bám.</li></ul>'),
(4, N'Ấm Tích Bát Tràng Vẽ Chuồn Trúc', 336000.0, N'dsc08201_4565768306424ce08246f6df224fd95a_medium.jpg', N'am-tich-bat-trang-ve-chuon-truc', N'Ấm Tích Bát Tràng Vẽ Chuồn Trúc, Sản phẩm nổi bật - Bộ ấm chén trà, Bộ Ấm Tích, Gốm Sứ Gia Dụng, Bộ Ấm Chén Trà, ấm chén, phanloai_bộ ấm tích, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ấm Tích Bát Tràng Vẽ Chuồn Trúc thuộc dòng sản phẩm ấm chén, được rất nhiều khách hàng quan tâm lựa chọn. Sản phẩm dùng để hãm chè xanh mang tới nhiều ưu điểm nổi bật trong quá trình...', N'<ul><li><strong>Tên sản phẩm:</strong> Ấm Tích Bát Tràng Vẽ Chuồn Trúc</li><li><strong>Chất liệu:</strong> Gốm sứ cao cấp</li><li><strong>Họa tiết: </strong>Chuồn chuồn, nhành trúc</li><li><strong>Màu men: </strong>Kem</li><li><strong>Dung tích: </strong>0.3l, 0.5l, 0.7l, 1l, 1.5l, 2l</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li><strong>Công dụng:</strong> Ấm tích không chỉ là công cụ để đựng nước trà mà còn được xem là vật dụng trang trí và thể hiện giá trị nghệ thuật của đồ thủ công mỹ nghệ.</li></ul>'),
(4, N'Ấm Tích Bát Tràng Vẽ Hoa Sen', 336000.0, N'dsc08244_b96873b1dcb14756bc1bca72655622ea_medium.jpg', N'am-tich-bat-trang-ve-hoa-sen', N'Ấm Tích Bát Tràng Vẽ Hoa Sen, Sản phẩm nổi bật - Bộ ấm chén trà, Bộ Ấm Tích, Gốm Sứ Gia Dụng, Bộ Ấm Chén Trà, ấm chén, phanloai_bộ ấm tích, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ấm Tích Bát Tràng Vẽ Hoa Sen thuộc dòng sản phẩm ấm chén, được rất nhiều khách hàng quan tâm lựa chọn. Sản phẩm dùng để hãm chè xanh mang tới nhiều ưu điểm nổi bật trong quá trình sử dụng và cho ra hương vị chè thơm ngon đúng điệu.', N'<ul><li><strong>Tên sản phẩm:</strong> Ấm Tích Bát Tràng Vẽ Hoa Sen</li><li><strong>Chất liệu:</strong> Gốm sứ cao cấp</li><li><strong>Họa tiết: </strong>Hoa Sen</li><li><strong>Màu men: </strong>Trắng</li><li><strong>Dung tích: </strong> 0.3l, 0.5l, 0.7l, 1l, 1.5l, 2l</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li><strong>Công dụng:</strong> Ấm tích không chỉ là công cụ để đựng nước trà mà còn được xem là vật dụng trang trí và thể hiện giá trị nghệ thuật của đồ thủ công mỹ nghệ.</li></ul>'),
(4, N'Bộ Ấm Chén Ấm Cao Múi Hoa', 2200000.0, N'1_36fc73bc36a94977ab64b77658c9a469_medium.jpg', N'bo-am-chen-am-cao-mui-hoa', N'Bộ Ấm Chén Ấm Cao Múi Hoa, Bộ Trà Men Hỏa Biến, Bộ Ấm Chén Trà, ấm chén, phanloai_bộ ấm trà men hỏa biến, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bộ Ấm Chén Ấm Cao Múi Hoa là tâm huyết của các nghệ nhân Bát Tràng – không chỉ giữ gìn nét truyền thống mà còn nâng tầm gốm Việt lên một đẳng cấp mới. Nếu quý khách đang tìm kiếm một bộ ấm chén mang tinh thần truyền thống nhưng vẫn khoác lên', N'<ul><li><strong>Tên sản phẩm:</strong> Bộ Ấm Chén Ấm Cao Múi Hoa</li><li><strong>Chất liệu:</strong> Men hỏa biến</li><li><strong>Họa tiết: </strong>Vân chấm</li><li><strong>Màu men: </strong>Xám đen</li><li><strong>Số món: </strong>1 ấm, 6 chén, 7 đĩa kê</li><li><strong>Phụ kiện đi kèm: </strong>Gạt tàn, ống tăm, hũ trà, cốc tống, ống đựng phụ kiện. Một bộ trà đầy đủ phụ kiện sẽ đáp ứng và làm hài lòng mọi nhu cầu của người sử dụng</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li><strong>Công dụng:</strong> Sử dụng uống trà, trang trí trưng bày trên bàn gỗ, bàn kính, bàn đá… trong phong khách, phòng làm việc, không gian sân vườn hoặc làm quà tặng,...</li></ul>'),
