(5, N'Chum Sành Cá Chép Vượt Vũ Môn Kim Sa Chạm Nổi Dát Vàng', 14500000.0, N'1_cc9ec0b4f29f44f686329dd788b3183a_medium.jpg', N'chum-sanh-ca-chep-vuot-vu-mon-dat-vang', N'Chum Sành Cá Chép Vượt Vũ Môn Kim Sa Chạm Nổi Dát Vàng, Chum Vò Ngâm Rượu, Sản phẩm nổi bật - Chum vò hũ gạo, Hũ Gạo, Chum Vò Rượu, chum ngâm rượu, phanloai_chum rượu, phanloai_chum không tráng men, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Chum Sành Cá Chép Vượt Vũ Môn Kim Sa Chạm Nổi Dát Vàng nhờ kết cấu sành rắn chắc, khả năng dẫn nhiệt kém, chum giúp đẩy nhanh quá trình phân tách rượu, làm cho rượu ngấu êm, đậm vị mà không gây đau đầu khi thưởng thức. Đây chính là điểm nổi bật làm nên chất lượng vượt trội của sản phẩm.', N'<ul><li><strong>Tên sản phẩm</strong>: Chum Sành Cá Chép Vượt Vũ Môn Kim Sa Chạm Nổi Dát Vàng</li><li><strong>Dung tích</strong>: 50Lít, 100Lít</li><li><strong>Chất liệu</strong>: Sành cao cấp lọc bỏ các tạp chất</li><li><strong>Họa tiết</strong>: Cá Chép Vượt Vũ Môn khắc thủ công đắp nổi dát vàng 24K</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Đựng gạo và trang trí không gian nhà</li><li><strong>Ưu điểm:</strong> Nắp đậy kín chống mối mọt, gián, kiến.</li></ul>'),
(5, N'Chum Sành Ngâm Rượu Nắp Lớn Không Tráng Men', 595000.0, N'chum-sanh-ngam-ruou-nap-lon-khong-trang-men_0dd32a5577cf4cc2827dc08b18b2ed16_medium.jpg', N'chum-sanh-ngam-ruou-nap-lon-khong-trang-men', N'Chum Sành Ngâm Rượu Nắp Lớn Không Tráng Men, Chum Vò Ngâm Rượu, ƯU ĐÃI MỚI NHẤT, Hũ Gạo, Chum Vò Rượu, phanloai_chum rượu, phanloai_chum không tráng men, phanloai_chum hạ thổ, phanloai_chum sành, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Chum Sành Ngâm Rượu Nắp Lớn Không Tráng Men mang trong mình nét đẹp văn hóa lâu đời của người Việt. Từ xa xưa, chum sành đã được dùng để bảo quản rượu, nước mắm, tương, dưa cà, tượng trưng cho sự sung túc, no đủ trong mỗi gia đình.', N'<ul><li><strong>Tên sản phẩm</strong>: Chum Sành Ngâm Rượu Nắp Lớn Không Tráng Men</li><li><strong>Dung tích</strong>: 30L, 50L, 100L</li><li><strong>Chất liệu</strong>: Gốm sành được nung ở nhiệt độ cao đã lọc bỏ tạp chất, không tráng men</li><li><strong>Công dụng</strong>: Ngâm rượu hoặc dùng trang trí không gian nhà</li><li><strong>Lưu ý</strong>: Chất đất được chọn lọc kỹ lưỡng nên không hở khí, không rỉ rượu. Loại bỏ tạp chất trong rượu, đảm bảo an toàn sức khỏe người dùng. Chum có nắp đảm bảo độ kín.</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li></ul>'),
(5, N'Chum Ngâm Rượu Trống Đồng', 360000.0, N'chum-ngam-ruou-trong-dong-4_3f02a9bddba74f5292b91bf33548a914_medium.jpg', N'chum-ngam-ruou-trong-dong', N'Chum Ngâm Rượu Trống Đồng, Chum Vò Ngâm Rượu, ƯU ĐÃI MỚI NHẤT, Sản phẩm nổi bật - Chum vò hũ gạo, Hũ Gạo, Chum Vò Rượu, chum trống đồng, chum ngâm rượu, Chum Ngâm Rượu Trống Đồng, phanloai_chum sành, phanloai_chum không tráng men, phanloai_chum rượu, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Chum Ngâm Rượu Trống Đồng được sản xuất nhiều dung tích: 5L, 10L,  20L, 30L, 40L, 50L, 70L, 100L bằng chất liệu sành đắp nổi cao cấp. Chum trống đồng là sản phẩm đa dụng dùng trong ngâm và ủ rượu tạo ra loại rượu thơm ngon đặc biệt. Ngoài ra, với thiết kế hai nắp chum còn được sử dụng để đựng gạo hoặc trang trí.', N'<ul><li><strong>Tên sản phẩm</strong>: Chum Ngâm Rượu Trống Đồng </li><li><strong>Dung tích</strong>: 5L, 10L,  20L, 30L, 50L, 100L</li><li><strong>Chất liệu</strong>: Gốm sành được nung ở nhiệt độ cao đã lọc bỏ tạp chất, không tráng men</li><li><strong>Họa tiết</strong>: Khắc chìm và đắp nổi hoa văn con người, chim thú và nhà sàn lấy cảm hứng từ mặt trống đồng Đông Sơn</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Gốm Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Ngâm rượu, đựng gạo, trang trí không gian nhà</li><li><strong>Ưu điểm:</strong> Khử Andehit bằng cách bằng cách thẩm thấu qua thành sản phẩm, an toàn sức khỏe người dùng.</li></ul>'),
(5, N'Vò Ngâm Rượu Họa Tiết Tiên Ông Đánh Cờ Vẽ Màu', 450000.0, N'dsc09646_a99001ca36a24c54afd6bd1b37a290cb_medium.jpg', N'vo-ngam-ruou-hoa-tiet-tien-ong-danh-co-ve-mau-1', N'Vò Ngâm Rượu Họa Tiết Tiên Ông Đánh Cờ Vẽ Màu, Chum Vò Ngâm Rượu, Sản phẩm nổi bật - Chum vò hũ gạo, Hũ Gạo, Chum Vò Rượu, chum ngâm rượu, phanloai_chum rượu, phanloai_vò gốm, phanloai_chum tráng men, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Vò Ngâm Rượu Họa Tiết Tiên Ông Đánh Cờ Vẽ Màu vẽ họa tiết ba tiên ông đang ngồi luận cơ say sưa trong một không gian đậm chất bồng lai tiên cảnh và nổi trên bề mặt chiếc vò', N'<ul><li><strong>Tên sản phẩm:</strong> Vò Ngâm Rượu Họa Tiết Tiên Ông Đánh Cờ Vẽ Màu</li><li><strong>Chất liệu:</strong> Gốm sứ trắng</li><li><strong>Kiểu dáng:</strong> Vò có nắp</li><li><strong>Dung tích: </strong>10, 15l, 20l, 30l</li><li><strong>Họa tiết:</strong> Tiên ông đánh cờ vẽ màu</li><li><strong>Màu men:</strong> Men lam</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng ngâm rượu, đựng thực phẩm, trang trí, trưng bày nhà cửa hoặc làm quà tặng,... </li></ul>'),
(5, N'Bình Chóe Ngâm Rượu Men Lam Tứ Cảnh', 1800000.0, N'tu_canh_1cc405426cb14c89b77907bbb038975f_medium.jpg', N'choe-ngam-ruou-men-lam-tu-canh', N'Bình Chóe Ngâm Rượu Men Lam Tứ Cảnh, Sản phẩm nổi bật - Chum vò hũ gạo, Hũ Gạo, Chum Vò Rượu, men lam, phanloai_chóe ngâm rượu, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bình Chóe Ngâm Rượu Men Lam Tứ Cảnh sử dụng ngâm rượu, trang trí nhà ở hoặc phòng làm việc, bàn tiếp khách và còn có thể dùng làm quà tặng ý nghĩa cho những người yêu thích gốm sứ', N'<ul><li><strong>Tên sản phẩm:</strong> Bình Chóe Ngâm Rượu Men Lam Tứ Cảnh</li><li><strong>Chất liệu:</strong> Gốm sứ trắng</li><li><strong>Kiểu dáng:</strong> Bình chóe có nắp</li><li><strong>Họa tiết: </strong>Tứ cảnh Cúc - Trúc - Tùng - Mai</li><li><strong>Màu Men:</strong> Men lam</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng ngâm rượu, trang trí nhà ở hoặc phòng thờ, bàn tiếp khách, làm quà tặng,...</li></ul>'),
(5, N'Bộ Bình Rượu Khắc Nổi Hoa Sen Nền Vàng', 1200000.0, N'bo-binh-ruou-khac-noi-hoa-sen-nen-vang_ef14b7f0bf83485d9bb2b9e7e4eec117_medium.jpg', N'bo-binh-ruou-khac-noi-hoa-sen-nen-vang', N'Bộ Bình Rượu Khắc Nổi Hoa Sen Nền Vàng, Bộ Bình Rót Rượu Gốm Sứ, Hũ Gạo, Chum Vò Rượu, phanloai_bình rót rượu, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bộ Bình Rượu Khắc Nổi Hoa Sen Nền Vàng sang trọng, tinh xảo. Sản phẩm gốm sứ Bát Tràng độc bản, ý nghĩa phong thủy, thích hợp trưng bày và biếu tặng.', N'<ul><li><strong>Tên sản phẩm: </strong>Bộ Bình Rượu Khắc Nổi Hoa Sen Nền Vàng</li><li><strong>Chất liệu:</strong> Gốm sứ</li><li><strong>Họa tiết:</strong> Hoa Sen</li><li><strong>Số lượng:</strong> 1 bình, 6 chén</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Dùng để đựng rượu uống, thờ, làm quà tặng, quà lưu niệm......</li><li><strong>Đặc tính:</strong> Chất liệu an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được nồng độ rượu không bị bay hơi. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
