(7, N'Bình Hoa Dáng Chuông Vẽ Tay Họa Tiết Sen Cá Chép', 5900000.0, N'_dsc0038_d75985449cd14e31badbdf34485d9be7_medium.jpg', N'binh-hoa-dang-chuong-ve-tay-hoa-tiet-sen-ca-chep', N'Bình Hoa Dáng Chuông Vẽ Tay Họa Tiết Sen Cá Chép, Bình Hoa Cắm Mai Đào Tết, Bình Lọ Hoa, quà tặng, bình hoa, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bình Hoa Dáng Chuông Vẽ Tay Họa Tiết Sen Cá Chép là một tác phẩm gốm sứ thủ công tinh xảo, kết hợp hài hòa giữa hình dáng truyền thống và họa tiết biểu tượng giàu ý nghĩa. Sản phẩm không chỉ là món đồ trang trí sang trọng mà còn là vật phẩm phong thủy mang lại may mắn, tài lộc và sự thịnh vượng cho gia chủ.', N'<ul><li style="text-align: justify;"><strong>Tên sản phẩm:</strong> Bình Hoa Dáng Chuông Vẽ Tay Họa Tiết Sen Cá Chép</li><li style="text-align: justify;"><strong>Chất liệu:</strong> Gốm sứ</li><li style="text-align: justify;"><strong>Kiểu dáng: </strong>Dáng chuông</li><li style="text-align: justify;"><strong>Màu men:</strong> Men màu</li><li style="text-align: justify;"><strong>Kích thước: </strong>H58</li><li style="text-align: justify;"><strong>Họa tiết: </strong>Sen Cá Chép</li><li style="text-align: justify;"><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li style="text-align: justify;"><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li style="text-align: justify;"><strong>Công dụng:</strong> Cắm cành đào, mận rừng, thanh liễu, đào đông, mai vàng ngày Tết; làm quà tặng, quà biếu cho những người thân yêu.</li></ul>'),
(8, N'Bộ Ly Tách Cà Phê Long Phương', 40000.0, N'bo-ly-tach-ca-phe-long-phuong_aa713a8f4c4d4d62a081fe249ca98b6a_medium.jpg', N'bo-ly-tach-ca-phe-long-phuong', N'Bộ Ly Tách Cà Phê Long Phương, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly coffee, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bộ Ly Tách Cà Phê Long Phương có đến 3 kích thước cho quý khách hàng lựa chọn. Bộ ly tách không chỉ là vật dụng để uống trà hay cà phê, đây còn là vật dụng hàng ngày và thể hiện ', N'<ul><li><strong>Tên sản phẩm: </strong>Bộ Ly Tách Cà Phê Long Phương</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> <ul><li>S1: 50ml</li><li>S2: 120ml</li><li>S3: 150ml</li></ul></li><li><strong>Kích thước</strong>:<ul><li>S1: Chiều cao: 5.9cm, đường kính ly: 4.2cm</li><li>S2: Chiều cao: 7cm, đường kính ly: 5cm</li><li>S3: Chiều cao: 7.5cm, đường kính 5.4cm</li></ul></li><li><strong>Kiểu dáng:</strong> Dáng trụ</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống cà phê hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng của thức uống. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Bộ Ly Tách Cà Phê Sứ', 60000.0, N'bo-ly-tach-ca-phe-su_0a836fcbe807494a82762b3df894437f_medium.jpg', N'bo-ly-tach-ca-phe-su', N'Bộ Ly Tách Cà Phê Sứ, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly coffee, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bộ Ly Tách Cà Phê Sứ là sản phẩm chất lượng với chất sứ cứng cáp, đanh và sáng bóng. Tách cà phê tráng men không họa tiết thể hiện tinh thần đơn giản tinh tế nhưng cũng toát lên vẻ sang trọng. Tách sứ có quai cầm nhỏ vừa phải, cân đối', N'<ul><li><strong>Tên sản phẩm: </strong>Bộ Ly Tách Cà Phê Sứ</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> <ul><li>S1: 250ml</li><li>S2: 150ml</li></ul></li><li><strong>Kích thước</strong>:<ul><li>S1: Chiều cao: 6.5cm, đường kính ly: 8.5, đường kính đĩa: 15cm</li><li>S2: Chiều cao: 6cm, đường kính ly: 8, đường kính đĩa: 14cm</li></ul></li><li><strong>Kiểu dáng:</strong> Dáng trụ</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống cà phê hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng của thức uống. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Bộ Phin Cà Phê Gốm Sứ', 150000.0, N'phin-gom-hoa_72838d64bf584092bc1a0016457321d3_medium.jpeg', N'bo-phin-cafe-gom-su', N'Bộ Phin Cà Phê Gốm Sứ, Ly Ca Cốc Sứ, Gốm Sứ Gia Dụng, phin cốc cà phê, ly sứ, phanloai_ly coffee, phanloai_phin coffee, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bộ Phin Cafe Gốm Sứ được sản xuất theo kỹ thuật thủ công và nung chín ở nhiệt độ 1200 độ C, đảm bảo sức khỏe cho người dùng, chịu được những va đập nhẹ.', N'<ul><li><strong>Tên sản phẩm:</strong> Bộ Phin Cà Phê Gốm Sứ</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 210-300ml</li><li><strong>Họa tiết</strong>: Vẽ hoa, khắc chìm</li><li><strong>Kiểu dáng:</strong> Hình trụ quai vuông</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống cà phê hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu gốm sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Bộ Phin Cafe Men Hỏa Biến', 300000.0, N'bo-phin-cafe-men-hoa-bien_9ed1c719ebbb4d72a292bcfaa8f76e06_medium.jpg', N'bo-phin-cafe-men-hoa-bien', N'Bộ Phin Cafe Men Hỏa Biến, Ly Ca Cốc Sứ, Gốm Sứ Gia Dụng, Ly ca cốc sứ, phanloai_ly coffee, phanloai_ly men hỏa biến, phanloai_phin coffee, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bộ Phin Cafe Men Hỏa Biến là sản phẩm quen thuộc với những người yêu cà phê. Bộ phin gốm sứ được tráng men xanh hỏa biến với dòng chảy của nước men rất độc đáo. Phin cà phê gốm sứ an toàn với sức khỏe vì đã loại bỏ các tạp chất có trong đất sét khi nung.', N'<ul><li><strong>Tên sản phẩm: </strong>Bộ Phin Cafe Men Hỏa Biến</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Màu men</strong>: Men xanh hỏa biến</li><li><strong>Dung tích:</strong> <ul><li>Phin cà phê: 175ml</li><li>Hũ đường: 270ml</li><li>Chân đốt: 100ml</li></ul></li><li><strong>Kích thước</strong>:<ul><li>Phin cà phê: chiều cao 13cm | chiều ngang 9.5cm</li><li>Hũ đường: chiều cao 6cm | chiều ngang 7cm</li><li>Chân đốt: chiều cao 11cm | chiều ngang 7,5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Dáng trụ thấp</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Các Mẫu Ly Hỏa Biến', 60000.0, N'ly_hoa_bien_fc7bdd9dc6c24896ae6b8aed4c7d8e6a_medium.jpg', N'cac-mau-ly-hoa-bien', N'Các Mẫu Ly Hỏa Biến, Ly Ca Cốc Sứ, Gốm Sứ Gia Dụng, phanloai_ly sứ không quai, phanloai_ly men hỏa biến, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Hỏa Biến là một loại sản phẩm gốm sứ độc đáo và mang đến những điểm nổi bật và phong cách riêng mà không loại ly nào khác có thể sánh kịp. Từng chiếc ly thành những tác phẩm nghệ thuật độc đáo.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Hỏa Biến</li><li><strong>Chất liệu:</strong> Gốm sứ men hỏa biến</li><li><strong>Dung tích:</strong> 130, 180, 270, 300 ml</li><li><strong>Kiểu dáng:</strong> Hình trụ quai vuông</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Cốc Bia', 80000.0, N'a__2__77a584a2470747889b2e5069c689649e_medium.jpg', N'coc-bia', N'Cốc Bia, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly sứ màu, phanloai_ly bia, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Cốc Bia  là sản phẩm chất lượng với chất sứ cứng cáp. Cốc Bia có dáng quai cầm chữ C với 7 màu tươi sáng và dung tích 430ml. Cốc bia là sản phẩm thiết yếu có thể sử dụng hàng ngày, trong nhiều hoàn cảnh không chỉ riêng lúc uống bia.', N'<ul><li><strong>Tên sản phẩm:</strong> Cốc Bia</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 430ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 12cm </li><li>Đường kính miệng: 8cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ </li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Cốc Bia Đáy Dày', 85000.0, N'a__4__aa529f4455bb49c8a53f99f8f0cfc40b_medium.jpg', N'coc-bia-day-day', N'Cốc Bia Đáy Dày, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly bia, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Cốc Bia Đáy Dày có phần đế cao, dày dặn và to hơn so với đường kính miệng cốc. Cốc có 3 màu trắng, đen và be đơn giản. Ly dày dặn và cứng cáp nhưng không quá nặng tay khi cầm uống bia. Ngoài uống bia ra, ta còn có thể sử dụng ca bia để dùng ngũ cốc và các loại thức uống khác tùy nhu cầu.', N'<ul><li><strong>Tên sản phẩm:</strong> Cốc Bia Đáy Dày</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> <ul><li>S1: 550ml</li><li>S2: 450nl</li></ul></li><li><strong>Kích thước:</strong> <ul><li>S1: Chiều cao: 14cm, chiều ngang: 8 - 10.2cm</li><li>S2: Chiều cao: 13cm, chiều ngang: 7.5 - 10cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ </li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Cốc Bia Quai C Có Đế', 70000.0, N'a__3__4d9435e302694dddb42b82fa8e9de8b3_medium.jpg', N'coc-bia-quai-c-co-de', N'Cốc Bia Quai C Có Đế, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Tên sản phẩm: Cốc Bia Quai C Có ĐếChất liệu: Sứ cao cấp tráng menDung tích: 550mlKích thước: Chiều cao: 12cm Đường kính miệng: 8-9,5cmKiểu dáng: Hình trụ Thương hiệu: Không Gian Gốm Bát TràngXuất xứ: Xưởng Bát Tràng – Gia Lâm – Hà Nội Công dụng: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác..', N'<ul><li><strong>Tên sản phẩm: </strong>Cốc Bia Quai C Có Đế</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 550ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 12cm </li><li>Đường kính miệng: 8-9,5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ </li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Cốc Bia Quai Tai', 80000.0, N'a__1__710d41b181164df8a1ea74fe563e5958_medium.jpg', N'coc-bia-quai-tai', N'Cốc Bia Quai Tai, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly bia, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Cốc Bia Quai Tai có dáng quai cầm chữ C với 3 màu đơn giản và dung tích lớn tới 600ml. Cốc bia là sản phẩm thiết yếu có thể sử dụng hàng ngày, trong nhiều hoàn cảnh không chỉ riêng lúc uống bia. Ngoài giá trị sử dụng, quý vị có thể dùng ly để làm quà tặng cho những người thân yêu hoặc dùng trong quán ăn, nhà hàng', N'<ul><li><strong>Tên sản phẩm:</strong> Cốc Bia Quai Tai</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 600ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 14cm </li><li>Đường kính miệng: 8,5 - 10,5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ </li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Cốc Bia Quai Tay', 80000.0, N'a__6__3c73e99fbfcb498783f00384419f5a2c_medium.jpg', N'coc-bia-quai-tay', N'Cốc Bia Quai Tay, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly sứ màu, phanloai_ly bia, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Cốc Bia Quai Tay có thiết kế đơn giản, quai chữ C có ngấn dễ cầm. Cốc dáng hình trụ, chắc chắn nhưng không quá nặng tay tạo sử thoải mái khi sử dụng. Cốc Bia Quai Tay của Không Gian Gốm Bát Tràng thiết kế tinh tế, nhã nhặn phù hợp sử dụng trong văn phòng, phòng làm việc hay khách sạn và có nhiều ưu điểm.', N'<ul><li><strong>Tên sản phẩm:</strong> Cốc Bia Quai Tay</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 430ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 12cm </li><li>Đường kính miệng: 8cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ </li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Cốc Bia Quai Vuông', 80000.0, N'a__5__808e5dc7b813447193274a14ec4d413e_medium.jpg', N'coc-bia-quai-vuong', N'Cốc Bia Quai Vuông, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly sứ màu, phanloai_ly bia, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Cốc Bia Quai Vuông được nhiều khách hàng ưa chuộng  bởi màu sắc trang nhã, dù là trắng trơn hay viền chỉ vàng. Ca bia được sản xuất dựa trên quy trình nghiêm ngặt, được nung ở nhiệt độ ~ 1.300 loại bỏ hoàn toàn tạp chất giúp ly có độ bền, chịu được cường lực lớn, đẹp, an toàn.', N'<ul><li><strong>Tên sản phẩm:</strong> Cốc Bia Quai Vuông</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 430ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 12cm </li><li>Đường kính miệng: 8cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ quai vuông</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Lu Bia Gốm Sứ', 25000.0, N'lu-bia-gom-su_8483282b7c2b4b3a9ca289dec35b8823_medium.jpg', N'lu-bia-gom-su', N'Lu Bia Gốm Sứ, Ly Ca Cốc Sứ, Ly ca cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Lu uống bia có thiết kế như một chiếc chum ngâm rượu từ xưa. Lu có thiết kế miệng tròn ngắn, thân trên phình to và thon dần về đáy tương tự bảo bình phong thủy. Ngoài thiết kế dáng bầu truyền thống thì chum bia còn có thiết kế vuông thân trụ chữ nhật hoặc thiết kế hồ lô cách điệu.', N'<ul><li><strong>Tên sản phẩm</strong>: Lu Bia Gốm Sứ\</li><li><strong>Chất liệu</strong>: Gốm sứ Bát Tràng</li><li><strong>Dung tích:</strong> 400ml</li><li><strong>Kích thước</strong>:<ul><li>Lu bia bầu: chiều cao 10,5cm | chiều ngang 9,5cm</li><li>Lu bia vuông: chiều cao 11cm | chiều ngang 7,5cm</li><li>Lu bia hồ lô: chiều cao 10,5cm | chiều ngang 9,5cm</li></ul></li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Uống bia, trà đá, trà sữa, trà chanh, các loại nước ngọt,...</li><li><strong>Ý nghĩa:</strong> Tạo điểm nhấn khi trên bàn ăn, bàn tiệc. </li></ul>'),
(8, N'Ly Bầu Quai C', 30000.0, N'ly-bau-quai-c_835205a1fee24e2fbb11de48ea75564a_medium.jpg', N'ly-bau-quai-c', N'Ly Bầu Quai C, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ màu, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Bầu Quai C có dáng bầu tròn với quai cầm hình chữ C vừa tầm tay với 7 màu sắc nổi bật. Ly Bầu Quai C bằng sứ có nhiều ứng dụng trong cuộc sống hàng ngày, ly sứ dày dặn nên có thể dùng đựng nước, trà hay cà phê.', N'<ul><li><strong>Tên sản phẩm: </strong>Ly Bầu Quai C</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 330ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 10cm </li><li>Đường kính miệng: 8-4.7cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn bầu</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Bầu Quai C To Có Nắp', 160000.0, N'ly-quai-to-co-nap-hai-mau_3fb60ac4b15144339ceddef8028fa129_medium.jpg', N'ly-bau-quai-c-to-co-nap', N'Ly Bầu Quai C To Có Nắp, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ màu, phanloai_ly sứ có nắp, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Bầu Quai C To Có Nắp có thiết kế hình trụ với phần nắp đậy và lòng ly cùng màu mới lạ. Ly sứ dày dặn có quai cầm tiện lợi và nắp kín đáo giúp người sử dụng thưởng thức thức uống một cách trọn vẹn nhất. Ly sứ còn có thể khắc tên và lời nhắn hay thông điệp theo yêu cầu.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Bầu Quai C To Có Nắp</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 500ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 9.7cm</li><li>Đường kính: 9-9.5cm</li></ul></li><li><strong>Kiểu dáng: </strong>Hình trụ có nắp</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ: </strong>Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng: </strong>Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Bầu Quai Tim', 55000.0, N'ly-bau-quai-tim_e431eb1bfc8945b08a129a4df98f71be_medium.jpg', N'ly-bau-quai-tim', N'Ly Bầu Quai Tim, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Bầu Quai Tim dáng tròn bầu có quai tim đa dụng sử dụng được nhiều trường hợp với nhiều thức uống khác nhau. Ly Bầu nhỏ vừa phải nên giữ nhiệt tốt. Chất sứ từ ly của Không Gian Gốm Bát Tràng được ưa chuộng vì có độ đanh và dẻo dai nên rất bền bỉ.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Bầu Quai Tim</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 270ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 9cm </li><li>Đường kính miệng: 8-4.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn bầu</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Cà Phê Sứ Minh Châu', 15200.0, N'ly-ca-phe-su-minh-chau_8afccda32f6542c4a8819c3f267da5ec_medium.jpg', N'ly-ca-phe-su-minh-chau', N'Ly Cà Phê Sứ Minh Châu, Ly Ca Cốc Sứ, phanloai_ly sứ trắng, phanloai_ly coffee, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly tách cà phê sứ dày dặn và bền bỉ được sản xuất thủ công từ làng nghề gốm Bát Tràng. Thiết kế thân tách cân đối với quai vuông vừa vặn cùng màu trắng trang nhã. Bộ tách có đến 3 kích thước với 3 dung tích khác nhau cho khách hàng chọn lựa.', N'<ul><li><strong>Tên sản phẩm: </strong>Ly Cà Phê Sứ Minh Châu</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> <ul><li>Ly CF Minh Châu: 250ml</li><li>Ly CF Minh Châu S1: 60ml</li><li>Ly CF Minh Châu S2: 65ml</li></ul></li><li><strong>Kích thước</strong>:<ul><li>Ly CF Minh Châu: Chiều cao: 8cm, đường kính ly: 9cm</li><li>Ly CF Minh Châu S1: Chiều cao: 7.5cm, đường kính ly: 5.5cm</li><li>Ly CF Minh Châu S2: Chiều cao: 8.3cm, đường kính ly: 6.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Dáng trụ</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống cà phê hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng của thức uống. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Capuchino', 110000.0, N'ly-capuchino_31a5e00d6e5f4ebaaec74110c180b817_medium.jpg', N'ly-capuchino', N'Ly Capuchino, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly coffee, phanloai_ly capuccino, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Capuchino có thiết kế đơn giản, quai hình tim dễ cầm với thiết kế tối giản, tinh tế cứng cáp và dày dặn. Ly sứ không những là vật dụng thưởng thức capuchino mà còn thể hiện gu thẩm mỹ cá tính, nổi bật.', N'<ul><li><strong>Tên sản phẩm</strong>: Ly Capuchino</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 220ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 6.5cm</li><li>Đường kính miệng ly: 9cm</li><li>Đường kính đĩa: 14cm</li></ul></li><li><strong>Kiểu dáng</strong>: Hình tròn thấp</li><li><strong>Thương hiệu: </strong>Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Espresso', 80000.0, N'ly-espresso_4b3b89285054407a989ba660e99c439f_medium.jpg', N'ly-espresso', N'Ly Espresso, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly coffee, phanloai_ly espresso, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Espresso  có thiết kế đơn giản, quai tròn cân đối dễ cầm. Ly sứ dùng được với cả nước sôi và nước lạnh, đa dạng hóa cách sử dụng và thưởng thức của người dùng. Ngoài giá trị sử dụng, quý vị có thể dùng ly để làm quà tặng cho những người thân yêu.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Espresso</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 320-360-400ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 10-12-13cm</li><li>Đường kính miệng: 8.5-8.5-9cm</li><li>Đường kính đĩa: 14cm</li></ul></li><li><strong>Kiểu dáng: </strong>Hình nón cụt</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng: </strong>Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
