(8, N'Ly Lùn Quai C', 80000.0, N'ly-lun-quai-c_5184c67dafc344518382f0fd6e330897_medium.jpg', N'ly-lun-quai-c', N'Ly Lùn Quai C, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Lùn Quai C dáng trụ thấp, quai cầm chữ C tròn nhỏ và đồng bộ màu men với thân ly. Ly lùn có dung tích lớn lên đến 360ml nên có thể sử dụng để pha chế và thưởng thức nhiều loại thức uống như Cà phê hay Capuchino,... Ly giữ nhiệt và cách nhiệt tốt và có thể dùng ở nhiều nơi, nhiều ngữ cảnh.', N'<ul><li><strong>Tên sản phẩm: </strong>Ly Lùn Quai C</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 360ml</li><li><strong>Kích thước</strong>:<ul><li>Chiều cao: 9cm</li><li>Đường kính miệng: 9.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Dáng trụ thấp</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Lùn Quai Tim', 45000.0, N'ly-lun-quai-tim_10652c230936487296b92be38d29f94f_medium.jpg', N'ly-lun-quai-tim', N'Ly Lùn Quai Tim, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Vẽ Tay Có Nắp có thiết kế thân trụ thấp và quai tim nhỏ nhắn, cân đối tạo cảm giác sang trọng, tao nhã khi sử dụng. Ly đơn giản nhưng dày dặn và dẻo dai nên có độ bền và tính thẩm mỹ cao.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Lùn Quai Tim</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 360ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 8cm </li><li>Đường kính miệng: 9.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ thấp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Melano', 60000.0, N'ly-melano_e36826aa441a49e2ba074d6c087bae48_medium.jpg', N'ly-melano', N'Ly Melano, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Melano bằng sứ phối màu ly với lòng trắng và bề mặt màu sắc khác nhau. Ly Melano có thiết kế trụ ngắn, phần miệng hơi co lại cho ra dáng ly mới lạ và độc đáo. Ly Melano có thiết kế đơn giản, quai hình trái tim cách điệu dễ cầm.', N'<ul><li><strong>Tên sản phẩm</strong>: Ly Melano</li><li><strong>Chất liệu</strong>: Sứ cao cấp tráng men</li><li><strong>Dung tích</strong>: 230ml</li><li><strong>Kích thước</strong>: <ul><li>Chiều cao: 7cm</li><li>Đường kính: 7-7.8cm</li></ul></li><li><strong>Kiểu dáng</strong>: Hình tròn thấp</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Nắp Ngọn Lửa', 60000.0, N'ly-nap-ngon-lua_3abf15fba4d34d43aeb35a68c885e321_medium.jpg', N'ly-nap-ngon-lua', N'Ly Nắp Ngọn Lửa, Ly Ca Cốc Sứ, ly cốc sứ, ly cốc bát tràng, phanloai_ly sứ có nắp, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Nắp Ngọn Lửa sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác. Ly có thiết kế cách điệu từ phần thân đến quai cầm và nắp. Ly sứ dùng được với cả nước sôi và nước lạnh, đa dạng hóa cách sử dụng và thưởng thức của người dùng. Nắp đậy giúp bảo quản thức uống khỏi bụi bẩn và côn trùng xâm nhập.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Nắp Ngọn Lửa</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 350ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 10cm</li><li>Đường kính: 8.5-4.9cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn cao có nắp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Nắp Ngọn Lửa In Decal', 80000.0, N'ly-nap-ngon-lua-in-decal_2a643b2bfcae4af4aa971eb63d8df4f0_medium.jpg', N'ly-nap-ngon-lua-in-decal', N'Ly Nắp Ngọn Lửa In Decal, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ có nắp, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Nắp Ngọn Lửa In Decal có hai thiết kế vẽ hoa văn và vẽ vàng cùng nắp đậy hình ngọn lửa kín đáo. Ly Nắp Ngọn Lửa In Decal thiết kế kiểu dáng bầu bĩnh, tinh tế nhưng vẫn cực kỳ nhã nhặn, thanh thoát, nổi bật và dễ cầm khi sử dụng.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Nắp Ngọn Lửa In Decal</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 350ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 10cm</li><li>Đường kính: 8.5-4.9cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn cao có nắp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai C Lùn Men Bóng', 30000.0, N'ly-quai-c-lun-men-bong_df165c9bab774377a7a503668fb52d82_medium.jpg', N'ly-quai-c-lun-men-bong', N'Ly Quai C Lùn Men Bóng, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Quai C Lùn Men Bóng có thiết kế tối giản, thân trụ ngắn và lòng trắng sáng bóng, mặt ngoài tráng 6 màu men bóng hiện đại thích hợp sử dụng và làm quà tặng. Ly sứ quai C được sản xuất từ nguồn nguyên liệu sạch. Đất sét được chọn lọc kỹ, và trải qua nhiều công đoạn sàn lọc mới đưa vào sản xuất.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Quai C Lùn Men Bóng</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 300ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 8.3cm</li><li>Đường kính: 8.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ thấp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ: </strong>Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai C Lùn Men Nhám', 30000.0, N'14_69951fec967e4f8a969cc972b19519ac_medium.jpg', N'ly-quai-c-lun-men-nham', N'Ly Quai C Lùn Men Nhám, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ trắng, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Quai C Lùn Men Nhám có dáng trụ thấp quai C nhỏ gọn và cân đối cùng lớp men nhám lì trơn mịn. Ly không quá cao, thành ly không quá dày nên có thể đựng được nhiều loại thức uống khác nhau.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Quai C Lùn Men Nhám</li><li><strong>Chất liệu: </strong>Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 300ml</li><li><strong>Kích thước</strong>: <ul><li>Chiều cao: 8.3cm</li><li>Đường kính: 8.5cm</li></ul></li><li><strong>Kiểu dáng: </strong>Hình tròn thấp</li><li><strong>Thương hiệu: </strong>Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ: </strong>Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng: </strong>Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai To Cao', 100000.0, N'ly-quai-to-cao_f218d7a635584d5b97d6cd88aac5238b_medium.jpg', N'ly-quai-to-cao', N'Ly Quai To Cao, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly quai to cao gốm sứ có dung tích lên đến 500ml và 6 màu sắc, hoa văn khác nhau. Ly có độ dày dặn đáng kể cùng quai to nên rất dễ cầm, đồng thời có nhiều ứng dụng trong cuộc sống hàng ngày, ly sứ dày dặn nên có thể dùng đựng nước, trà hay cà phê và nhiều thức uống khác.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Quai To Cao</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 500ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 8cm </li><li>Đường kính miệng: 9-9.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình trụ thấp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai To Có Nắp', 160000.0, N'ly-quai-to-co-nap_3f0c5600d44c4e46848f5ce5f3919fa2_medium.jpg', N'ly-quai-to-co-nap', N'Ly Quai To Có Nắp, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ có nắp, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Quai To Có Nắp có thiết kế đơn giản với màu men trắng và chấm bi màu. Ly sứ to kèm nắp đậy kín đáo có nhiều ứng dụng trong cuộc sống hàng ngày, ly sứ dày dặn nên có thể dùng đựng nước, trà hay cà phê.', N'<ul><li><strong>Tên sản phẩm</strong>: Ly Quai To Có Nắp</li><li><strong>Chất liệu</strong>: Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 500ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 9.5cm</li><li>Đường kính: 9-9.5cm</li></ul></li><li><strong>Kiểu dáng</strong>: Hình tròn cao có nắp</li><li><strong>Thương hiệu: </strong>Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ: </strong>Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng: </strong>Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai To Có Nắp Full Màu', 160000.0, N'ly-quai-to-co-nap-full-mau_1d65a2376c614d2d9f90e4bd23dd955e_medium.jpg', N'ly-quai-to-co-nap-full-mau', N'Ly Quai To Có Nắp Full Màu, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly sứ màu, phanloai_ly sứ có nắp, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Quai To Có Nắp Full Màu là sản phẩm được ưa chuộng tại hệ thống Không Gian Gốm Bát Tràng. Ly quai to, cân đối, cốt gốm cứng cáp và khi cầm cho cảm giác nặng tay chất lượng. Ly trơn bóng đơn giản, thiết kế tinh tế với 8 màu pastel nhẹ nhàng, dịu mắt giúp giảm căng thẳng khi sử dụng.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Quai To Có Nắp Full Màu</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 500ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 9.7cm</li><li>Đường kính: 9-9.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn cao có nắp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính</strong>: Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai To In Decal', 100000.0, N'ly-quai-to-in-decal_c3206b8b6940484798b5971967296e05_medium.jpg', N'ly-quai-to-in-decal', N'Ly Quai To In Decal, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Quai To In Decal có thiết kế hiện đại với dáng quai C và họa tiết ngôi sao với hai màu xanh dương và hồng trẻ trung. Ly to cứng cáp có thể dùng được với nhiều loại thức uống nóng, lạnh khác nhau', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Quai To In Decal</li><li><strong>Chất liệu:</strong> Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 500ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 8.2cm</li><li>Đường kính: 9.5cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn cao có nắp</li><li><strong>Thương hiệu</strong>: Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ</strong>: Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng</strong>: Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính:</strong> Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(8, N'Ly Quai To Vuông', 130000.0, N'ly-quai-to-vuong_c094413f56e3499c8d603ac6dadccabb_medium.jpg', N'ly-quai-to-vuong', N'Ly Quai To Vuông, Ly Ca Cốc Sứ, Ly ca cốc sứ, phanloai_ly kiểu hiện đại, ly cốc sứ, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Ly Quai To Vuông có thiết kế đơn giản, quai hình chữ D to tròn dễ cầm. Ly trơn bóng đơn giản, thiết kế tinh tế với 6 màu sắc nổi bật trong lòng ly. Ly Quai To Vuông có tráng men lên bề mặt nên sản phẩm luôn có độ trơn bóng, sáng mịn.', N'<ul><li><strong>Tên sản phẩm:</strong> Ly Quai To Vuông</li><li><strong>Chất liệu</strong>: Sứ cao cấp tráng men</li><li><strong>Dung tích:</strong> 500ml</li><li><strong>Kích thước:</strong> <ul><li>Chiều cao: 10cm</li><li>Đường kính: 9-10cm</li></ul></li><li><strong>Kiểu dáng:</strong> Hình tròn cao có nắp</li><li><strong>Thương hiệu: </strong>Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội </li><li><strong>Công dụng:</strong> Sử dụng uống nước hàng ngày, làm quà tặng người thân, nhân viên, đối tác...</li><li><strong>Đặc tính: </strong>Chất liệu sứ an toàn, lành tính, sử dụng được nhiều lần. Chịu nhiệt tốt, giữ được độ nóng hoặc lạnh của thức uống tốt. Mặt men sáng bóng, cứng chắc, giữ sản phẩm luôn mới sau thời gian dài sử dụng.</li></ul>'),
(9, N'Bình Hút Lộc Hoa Sen Phú Quý', 2400000.0, N'qhl_7_4a909657e5ff4ab3be6b31c4b97db2a9_medium.png', N'binh-hut-loc-hoa-sen-phu-quy', N'Bình Hút Lộc Hoa Sen Phú Quý, Quà Tặng Đại Hội Đảng, Bộ Quà Tặng Gốm Sứ, quà tặng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bình Hút Lộc Hoa Sen Phú Quý bình được nung ở nhiệt độ cao nên loại bỏ được các tạp chất độc hại, độ bền cao, cho phép thời gian sử dụng lâu dài.', N'<ul><li><strong>Tên sản phẩm:</strong> Bình Hút Lộc Hoa Sen Phú Quý</li><li><strong>Chất liệu:</strong> Gốm sứ cao cấp</li><li><strong>Màu men: </strong>Men trắng</li><li><strong>Kích thước: </strong>H30</li><li><strong>Họa tiết: </strong>Hoa Sen Phú Quý</li><li><strong>In ấn:</strong> In logo theo yêu cầu</li><li><strong>Quy cách:</strong> Bao gói hộp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li><strong>Công dụng:</strong> Quà tặng ý nghĩa cho các dịp trọng đại như Đại hội, kỷ niệm, ngày thành lập cho tổ chức, cá nhân và doanh nghiệp. ...</li></ul>'),
(9, N'Bình Hút Lộc Men Đỏ Vẽ Vàng Sen Chép', 460000.0, N'qhl5_copy_7_9fd95ee1a7c6490ca32322047be217f7_medium.png', N'binh-hut-loc-men-do-ve-vang-sen-chep', N'Bình Hút Lộc Men Đỏ Vẽ Vàng Sen Chép, Quà Tặng Đại Hội Đảng, Bộ Quà Tặng Gốm Sứ, quà tặng, Không Gian Gốm Bát Tràng TpHCM, khonggiangom.com', N'Bình Hút Lộc Men Đỏ Vẽ Vàng Sen Chép thuộc dòng gốm sứ cao cấp tại Bát Tràng, không chỉ bởi hình thức sang trọng mà còn bởi chất liệu làm bình đạt chuẩn loại một. Đất sét tạo nên bình là chất đất sét cao lanh dẻo, mịn, khó tan trong nước', N'<ul><li><strong>Tên sản phẩm:</strong> Bình Hút Lộc Men Đỏ Vẽ Vàng Sen Chép</li><li><strong>Chất liệu:</strong> Gốm sứ cao cấp</li><li><strong>Màu men: </strong>Men đỏ</li><li><strong>Kích thước: </strong>H25</li><li><strong>Họa tiết: </strong>Sen chép</li><li><strong>In ấn:</strong> In logo theo yêu cầu</li><li><strong>Quy cách:</strong> Bao gói hộp</li><li><strong>Thương hiệu:</strong> Không Gian Gốm Bát Tràng</li><li><strong>Xuất xứ:</strong> Xưởng Bát Tràng – Gia Lâm – Hà Nội</li><li><strong>Công dụng:</strong> Quà tặng ý nghĩa cho các dịp trọng đại như Đại hội, kỷ niệm, ngày thành lập cho tổ chức, cá nhân và doanh nghiệp. ...</li></ul>'),
